const icon = name => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const number = (value,places=1) => value === null || value === undefined ? '—' : Number(value).toLocaleString('en-US',{minimumFractionDigits:places,maximumFractionDigits:places});
const el = id => document.getElementById(id);
const hostedVercel=document.body.dataset.hosted==='vercel';
const state={llm:null,connectEdit:false,documents:[],id:null,data:null,view:'overview',page:1,sourceMode:'image',range:'all',quality:'all',messages:new Map(),conversations:new Map(),overviewSeen:new Set(),asking:false,poll:null};
const views=[['overview','Pulse','grid'],['chat','Query','chat'],['source','Vault','file'],['quality','Data Audit','shield'],['extraction','Trace','log'],['architecture','Engine','architecture'],['connect','Connect AI','key']];
const prompts=[['Performance','What was the reported NAV and return for 2025?'],['Compare','How did the fund perform against the benchmark in 2025?'],['Reconcile','Does the 2025 annual NAV agree with the quarterly section?'],['Look ahead','What are the forecast NAV and AUM for 2030?']];

// Conversations stay in this browser, grouped by uploaded document.
const CHAT_STORAGE='fund-chats-v1';
const LLM_STORAGE='neuranx-llm-v1';
function conversationStore(){
 if(!state.conversations.has(state.id)){
  let saved;try{saved=JSON.parse(localStorage.getItem(CHAT_STORAGE)||'{}')[state.id]}catch{}
  const threads=Array.isArray(saved?.threads)?saved.threads.filter(t=>typeof t.id==='string'&&Array.isArray(t.messages)).map(t=>({...t,title:String(t.title||'New conversation').slice(0,100),messages:t.messages.filter(m=>typeof m.question==='string').map(m=>m.response||m.error?m:{...m,error:'This response was interrupted. Please ask again.'})})):[];
  state.conversations.set(state.id,{active:saved?.active,threads});
 }
 return state.conversations.get(state.id);
}
function activeConversation(){
 const store=conversationStore();let thread=store.threads.find(t=>t.id===store.active);
 if(!thread){thread={id:crypto.randomUUID(),title:'New conversation',updated:Date.now(),messages:[]};store.threads.unshift(thread);store.active=thread.id}
 state.messages.set(state.id,thread.messages);return thread;
}
function saveConversations(){
 try{const saved=JSON.parse(localStorage.getItem(CHAT_STORAGE)||'{}');for(const [id,store] of state.conversations)saved[id]={active:store.active,threads:store.threads};localStorage.setItem(CHAT_STORAGE,JSON.stringify(saved))}catch{toast('Chat history could not be saved in this browser. This session is still available.')}
}
function openConversation(id){const store=conversationStore();if(!store.threads.some(t=>t.id===id))return;store.active=id;activeConversation();saveConversations();render()}
function chatHistory(){const current=activeConversation();return `<aside class="chat-history" aria-label="Chat history"><div class="history-heading"><h2>Conversations</h2><span>In this browser</span></div><button class="button" id="new-chat" ${state.asking?'disabled':''}>${icon('plus')}New chat</button><div class="history-list">${[...conversationStore().threads].sort((a,b)=>b.updated-a.updated).map(t=>`<button class="history-item ${t.id===current.id?'selected':''}" data-conversation="${esc(t.id)}" ${t.id===current.id?'aria-current="true"':''}><span>${esc(t.title)}</span><small>${t.messages.length?new Date(t.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'Ready to start'}</small></button>`).join('')}</div><p class="history-note">History for this report is saved on this device.</p></aside>`}
function animateOverview(){
 if(state.view!=='overview'||state.overviewSeen.has(state.id))return;
 state.overviewSeen.add(state.id);
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const main=el('main');main.classList.add('overview-enter');
 main.querySelectorAll('.stat-value').forEach((node,index)=>{
  const original=node.textContent,visual=document.createElement('span');visual.setAttribute('aria-hidden','true');while(node.firstChild)visual.append(node.firstChild);node.append(visual);const label=document.createElement('span');label.className='sr-only';label.textContent=original;node.append(label);
  const walker=document.createTreeWalker(visual,NodeFilter.SHOW_TEXT),texts=[];while(walker.nextNode())texts.push(walker.currentNode);
  for(const text of texts){if(!/\d/.test(text.textContent))continue;const fragment=document.createDocumentFragment();
   for(const char of text.textContent){if(!/\d/.test(char)){fragment.append(document.createTextNode(char));continue}
    const digit=document.createElement('span');digit.className='rolling-digit';digit.setAttribute('aria-hidden','true');
    const strip=document.createElement('span');strip.className='digit-strip';strip.innerHTML='01234567890123456789'.split('').map(n=>`<span>${n}</span>`).join('');
    const target=`translateY(-${(10+Number(char))*1.2}em)`;strip.style.transform=target;digit.append(strip);fragment.append(digit);
    strip.animate([{transform:'translateY(0)'},{transform:target}],{duration:1100+index*100,easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'});
   }
   text.replaceWith(fragment);
  }
 });
}
function connect(){
 let saved=null;try{saved=JSON.parse(localStorage.getItem(LLM_STORAGE)||'null')}catch{}
 if(state.llm&&!state.connectEdit)return `${heading('Connect AI','Your provider key stays encrypted in this browser',false)}<section class="panel connect-panel"><div class="connect-status">${icon('check')}<div><strong>${state.llm.provider==='anthropic'?'Claude':'OpenAI'} is connected</strong><p>Key unlocked for this browser session. It is sent through Vercel with each question and used for that request.</p></div></div><div class="connect-actions"><button class="button" id="change-llm">Change provider or key</button><button class="button" id="lock-llm">Lock provider key</button><button class="button danger-button" id="remove-llm">Remove saved key</button></div></section>${llmPrivacy()}`;
 if(saved&&!state.connectEdit)return `${heading('Connect AI','Unlock your encrypted provider key',false)}<section class="panel connect-panel"><div class="connect-status"><div><strong>Encrypted ${saved.provider==='anthropic'?'Claude':'OpenAI'} key found</strong><p>It is stored only in this browser and cannot be recovered without your passphrase.</p></div></div><form id="unlock-llm" class="connect-form"><label>Encryption passphrase<input name="passphrase" type="password" minlength="12" autocomplete="current-password" required></label><p class="connect-feedback" id="connect-feedback" role="status"></p><button class="button primary" type="submit">Unlock for this session</button></form><button class="text-link" id="replace-llm">Replace saved connection</button></section>${llmPrivacy()}`;
 return `${heading('Connect AI','Use your own provider key for evidence based answers',false)}<section class="panel connect-panel"><form id="save-llm" class="connect-form"><label>Provider<select name="provider"><option value="anthropic">Claude · Anthropic</option><option value="openai">ChatGPT · OpenAI</option></select></label><label>API key<input name="apiKey" type="password" autocomplete="off" spellcheck="false" required placeholder="Paste your provider key"></label><label>Encryption passphrase<input name="passphrase" type="password" minlength="12" autocomplete="new-password" required placeholder="At least 12 characters"></label><label>Confirm passphrase<input name="confirmPassphrase" type="password" minlength="12" autocomplete="new-password" required></label><p class="connect-feedback" id="connect-feedback" role="status"></p><button class="button primary" type="submit">Encrypt and connect</button></form></section>${llmPrivacy()}`;
}
function llmPrivacy(){return `<section class="connect-privacy"><h2>How your key is handled</h2><ul><li>Your key is encrypted with AES-GCM in this browser; only the encrypted value is saved in local storage.</li><li>Your passphrase is not saved. Unlocking keeps the key in memory until you lock or refresh the page.</li><li>When you ask a question, the key and relevant report passages pass through this Vercel function to the provider you selected. The app does not save the key on its server.</li><li>The selected provider may process the question and report excerpts under its own account terms and billing.</li></ul></section>`}
const b64=bytes=>btoa(String.fromCharCode(...new Uint8Array(bytes)));
const unb64=value=>Uint8Array.from(atob(value),c=>c.charCodeAt(0));
async function deriveKey(passphrase,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function sealCredentials(provider,apiKey,passphrase){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveKey(passphrase,salt),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify({provider,apiKey})));return {version:1,provider,salt:b64(salt),iv:b64(iv),cipher:b64(cipher)}}
async function openCredentials(record,passphrase){if(record?.version!==1||!['anthropic','openai'].includes(record.provider))throw Error('Saved connection is invalid. Replace it to continue.');const key=await deriveKey(passphrase,unb64(record.salt)),raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(record.iv)},key,unb64(record.cipher)),value=JSON.parse(new TextDecoder().decode(raw));if(value.provider!==record.provider||typeof value.apiKey!=='string')throw Error('Saved connection is invalid.');return value}
async function api(path,options={}){
  const r=await fetch(path,options);
  if(!r.ok){let detail;try{const b=await r.json();detail=typeof b.detail==='string'?b.detail:JSON.stringify(b.detail)}catch{}throw new Error(detail||`Request failed (${r.status})`)}
  return r.json();
}
function toast(text){el('toast').textContent=text;el('toast').hidden=false;clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el('toast').hidden=true,4500)}
function theme(value){document.documentElement.dataset.theme=value;try{localStorage.setItem('fund-theme',value)}catch{}el('light-theme').classList.toggle('selected',value==='light');el('dark-theme').classList.toggle('selected',value==='dark');el('light-theme').setAttribute('aria-pressed',value==='light');el('dark-theme').setAttribute('aria-pressed',value==='dark')}
function nav(){el('nav').innerHTML=views.map(([key,label,ic])=>`<a href="#${key}" class="nav-item ${state.view===key?'active':''}" ${state.view===key?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${key==='quality'&&state.data?.issues?.length?`<span class="nav-count">${state.data.issues.filter(x=>x.status==='open').length}</span>`:''}</a>`).join('');el('breadcrumb-current').textContent=views.find(x=>x[0]===state.view)?.[1]||'Pulse'}
function pageButton(page,label){return `<button class="metric-source" data-evidence="${Number(page)}" aria-label="View evidence on page ${Number(page)}">${esc(label||`p. ${page}`)}</button>`}
function cite(source,label){return `<button class="citation-chip" data-evidence="${source.page}">${icon('file')}<span>${esc(label||`p. ${source.page} · ${source.section}`)}</span>${icon('arrow')}</button>`}
function heading(title,subtitle,actions=true){return `<div class="page-heading"><div><div class="eyebrow">Financial document intelligence</div><h1 class="page-title">${esc(title)}</h1><p class="page-subtitle">${esc(subtitle)}</p></div>${actions?`<div class="heading-actions"><button class="button" data-export>${icon('download')}Export findings</button><button class="button primary" data-upload ${hostedVercel?'hidden':''}>${icon('upload')}Add report</button></div>`:''}</div>`}
function recordFact(metric,period,classification='historical'){return state.data?.facts.find(f=>f.metric===metric&&f.period===String(period)&&f.classification===classification)}
function shortMetric(metric){return metric.replaceAll('_',' ').replace(/^./,s=>s.toUpperCase())}
function renderDetails(details){return Object.entries(details).map(([key,value])=>`<div class="detail-item"><span class="detail-label">${esc(shortMetric(key).replace(/\bnav\b/gi,'NAV'))}</span><div class="detail-value">${Array.isArray(value)?value.map(item=>typeof item==='object'?`<div class="detail-version">${Object.entries(item).map(([k,v])=>`${esc(shortMetric(k).replace(/\bnav\b/gi,'NAV'))}: ${esc(Array.isArray(v)?v.join(', '):v)}`).join(' · ')}</div>`:esc(item)).join(typeof value[0]==='object'?'':', '):esc(value)}</div></div>`).join('')}
function reportStrip(){const d=state.data.document;return `<div class="report-strip">${icon('file')}<span class="report-filename" title="${esc(d.filename)}">${esc(d.filename)}</span><span class="strip-divider"></span><span class="secondary strip-meta">${d.page_count} pages</span><span class="secondary strip-meta">·</span><span class="secondary strip-meta">${d.fact_count} extracted facts</span><span class="verified">${icon('check')}Ready to explore</span></div>`}
function stat(label,value,note,fact){return `<div class="stat"><div class="stat-label">${esc(label)} ${fact?pageButton(fact.source.page):''}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function chart(){
 let historical=state.data.annual.filter(x=>x.nav!==null),forecast=state.data.forecast.filter(x=>x.nav!==null);
 const rows=state.range==='historical'?historical:state.range==='forecast'?[...(historical.length?[historical.at(-1)]:[]),...forecast]:[...historical,...forecast];
 if(rows.length<2)return '<div class="empty-inline">Not enough NAV observations to draw a trend</div>';
 const W=720,H=292,L=44,R=36,T=32,B=36,vals=rows.map(x=>Number(x.nav)),min=Math.floor(Math.min(...vals)/50)*50,max=Math.ceil(Math.max(...vals)/50)*50||50;
 const x=i=>L+i*(W-L-R)/(rows.length-1),y=v=>T+(max-Number(v))*(H-T-B)/(max-min||1);
 const isForecast=r=>r.classification==='forecast';
 const histPoints=rows.map((r,i)=>({r,i})).filter(({r})=>!isForecast(r));
 const forecastPoints=rows.map((r,i)=>({r,i})).filter(({r,i})=>isForecast(r)||(!isForecast(r)&&isForecast(rows[i+1]||{})));
 const line=points=>points.map(({r,i},j)=>`${j?'L':'M'}${x(i).toFixed(1)},${y(r.nav).toFixed(1)}`).join(' ');
 const firstForecast=rows.findIndex(isForecast),regionStart=firstForecast>0?(x(firstForecast-1)+x(firstForecast))/2:L;
 let svg=`<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Reported and forecast net asset value, ${esc(rows[0].year)} to ${esc(rows.at(-1).year)}"><title>NAV from source tables. Dashed values are forecasts, not historical outcomes.</title>`;
 if(firstForecast>=0)svg+=`<rect class="chart-region" x="${regionStart}" y="${T-16}" width="${W-R-regionStart}" height="${H-B-T+16}" rx="4"/><text class="chart-annotation" x="${regionStart+12}" y="${T}">Forecast</text>`;
 for(let i=0;i<=4;i++){const v=min+(max-min)*i/4,yy=y(v);svg+=`<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="chart-label" text-anchor="end" x="${L-12}" y="${yy+4}">${number(v,0)}</text>`}
 svg+=`<defs><clipPath id="nav-series-clip"><rect class="nav-reveal-rect" x="0" y="0" width="${W}" height="${H}"/></clipPath></defs><g clip-path="url(#nav-series-clip)">`;
 if(histPoints.length)svg+=`<path class="chart-line" d="${line(histPoints)}"/>`;
 if(forecastPoints.length)svg+=`<path class="chart-line chart-forecast" d="${line(forecastPoints)}"/>`;
 rows.forEach((r,i)=>{svg+=`<circle class="chart-dot" cx="${x(i)}" cy="${y(r.nav)}" r="${i===rows.length-1||(!isForecast(r)&&isForecast(rows[i+1]||{}))?4:2.5}"/><text class="chart-label" text-anchor="middle" x="${x(i)}" y="${H-12}">${r.year}</text><rect class="chart-hit" tabindex="0" role="button" aria-label="${r.year} NAV ${number(r.nav,1)}${isForecast(r)?' forecast':''}, view source page ${r.page}" data-chart-year="${r.year}" data-chart-nav="${r.nav}" data-chart-page="${r.page}" data-chart-forecast="${isForecast(r)}" data-evidence="${r.page}" x="${x(i)-20}" y="${T}" width="40" height="${H-B-T}"><title>${r.year}: ${number(r.nav,1)} · ${isForecast(r)?'Forecast':'Historical'} · p. ${r.page}</title></rect>`});
 svg+='</g></svg>';
 const pages=[...new Set(rows.map(r=>r.page))];
 return `<div class="chart-box">${svg}<div class="chart-tooltip" id="chart-tooltip" hidden></div></div><div class="chart-footer"><div class="legend"><span><i></i>Reported NAV</span><span><i class="dashed"></i>Forecast NAV</span></div><button class="text-link" data-evidence="${pages[0]}">Source tables ${icon('arrow')}</button></div>`;
}
function annualTable(){
 const rows=state.data.annual;
 if(!rows.length)return '<div class="empty-inline">No annual performance table was identified in this report</div>';
 return `<div class="table-wrap"><table><thead><tr><th>Year</th><th>NAV</th><th>Fund return</th><th>Benchmark</th><th>Evidence</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i===rows.length-1?'highlight':''}"><td><div class="year-cell">${r.year}${state.data.issues.some(x=>x.severity!=="info"&&x.fact_ids.some(id=>state.data.facts.find(f=>f.id===id&&f.period===r.year)))?'<span class="row-warning" title="Related data-quality finding">*</span>':''}</div></td><td class="mono">${number(r.nav)}</td><td class="mono">${number(r.fund_return)}%</td><td class="mono">${number(r.benchmark_return)}%</td><td>${pageButton(r.page)}</td></tr>`).join('')}</tbody></table></div><div class="table-note">* A source consistency check needs review · Values remain as reported</div>`;
}
function allocations(){
 const groups=state.data.allocations,group=groups.find(g=>g.name.toLowerCase().includes('sector'))||groups[0];
 if(!group)return '<div class="empty-inline">No allocation table was identified</div>';
 return `<div class="allocation-content"><div class="allocation-total">${esc(group.name)} · As reported in source</div>${group.rows.map((r,i)=>`<div class="allocation-item"><div class="allocation-row"><span>${esc(r.category)}</span><span class="allocation-value">${number(r.value,0)}%</span></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,Number(r.value)))}%;opacity:${i===0?1:Math.max(.22,.6-i*.09)}"></div></div></div>`).join('')}</div><div class="allocation-foot"><span>${group.rows.length} categories · ${number(group.rows.reduce((s,r)=>s+Number(r.value),0),0)}% total</span>${pageButton(group.page,'View evidence ↗')}</div>`;
}
function issuePreview(){const issue=state.data.issues.find(x=>x.rule==='nav_return_mismatch')||state.data.issues[0];if(!issue)return '<div class="issue-summary"><h3>No consistency findings</h3><p>The implemented checks did not detect a discrepancy. Review the source to assess checks that need human judgment.</p></div>';return `<div class="issue-summary"><h3>${esc(issue.title)}</h3><p>${esc(issue.description)}</p>${issue.details.reported!==undefined?`<div class="comparison"><div class="comparison-cell"><span>Reported return</span><strong>${number(issue.details.reported)}%</strong></div><div class="comparison-cell warning"><span>NAV-implied return</span><strong>${number(issue.details.computed)}%</strong></div></div>`:''}</div><div class="issue-panel-footer"><span>Source values preserved</span><a class="text-link" href="#quality">Review findings ${icon('right')}</a></div>`}
function queryForm(id,placeholder){return `<form class="query-form" id="${id}"><div class="query-input-wrap">${icon('chat')}<input class="query-input" name="question" aria-label="Question about the report" placeholder="${esc(placeholder)}" maxlength="2000" required autocomplete="off"><button class="query-send" type="submit" aria-label="Ask question" ${state.asking?'disabled':''}>${icon('send')}</button></div></form>`}
function overview(){const d=state.data,last=d.annual.at(-1),nav=last&&recordFact('nav',last.year),ret=last&&recordFact('fund_return',last.year),benchmark=last&&recordFact('benchmark_return',last.year);return `${heading(d.title||'Pulse','Fund performance, portfolio analysis & forecast')}${reportStrip()}<div class="stats">${stat(`Reported NAV · ${last?.year||'—'}`,last?number(last.nav,2):'—','Historical · Source-reported',nav)}${stat(`Annual return · ${last?.year||'—'}`,last?`${number(last.fund_return)}<span class="unit">%</span>`:'—',last?`<span class="positive">${number(last.fund_return-last.benchmark_return)} pp</span> vs benchmark`:'No historical return available',ret)}${stat('Forecast horizon',d.forecast.length?`${d.forecast.at(-1).year}`:'—',d.forecast.length?`${d.forecast.length} years of source projections`:'No forecasts identified',d.forecast.length?recordFact('nav',d.forecast.at(-1).year,'forecast'):null)}${stat('Data quality',String(d.issues.filter(x=>x.status==='open').length),`<span class="warning-ink">Open findings</span> · Review before use`,null)}</div><div class="overview-grid"><section class="panel chart-panel"><div class="panel-header"><div><h2 class="panel-title">Net asset value</h2><p class="panel-subtitle">${esc(d.nav_unit||'NAV units')} · Historical performance and outlook</p></div><div class="segmented" role="group" aria-label="Chart period">${[['historical','Historical'],['all','All years'],['forecast','Forecast']].map(([v,label])=>`<button data-range="${v}" class="${state.range===v?'selected':''}" aria-pressed="${state.range===v}">${label}</button>`).join('')}</div></div>${chart()}</section><section class="panel"><div class="panel-header"><h2 class="panel-title">Portfolio composition</h2>${icon('info')}</div>${allocations()}</section></div><div class="lower-grid"><section class="panel"><div class="panel-header"><h2 class="panel-title">Annual performance</h2><span class="panel-subtitle">Historical · ${d.annual[0]?.year||'—'}–${last?.year||'—'}</span></div>${annualTable()}</section><section class="panel"><div class="panel-header"><h2 class="panel-title">A closer look at the numbers</h2><span class="issue-count"><i></i>${d.issues.length} findings</span></div>${issuePreview()}</section></div><section class="ask-preview"><div class="ask-heading"><div><h2 class="panel-title">Query</h2><p>From a question to an answer you can verify</p></div><span class="evidence-note">${icon('shield')}Grounded in source evidence</span></div>${queryForm('overview-query','How did the fund perform against the benchmark in 2025?')}<div class="suggestions">${prompts.slice(0,3).map(([_,q])=>`<button class="suggestion" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div></section>`}
// Render a deliberately small Markdown subset. Raw HTML and links stay escaped.
function answerMarkdown(text){
 const inline=value=>esc(value).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 const lines=String(text||'').split(/\r?\n/),out=[];
 const cells=line=>line.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim());
 const separator=line=>/^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);
 for(let i=0;i<lines.length;){
  const line=lines[i];
  if(!line.trim()){i++;continue}
  if(i+1<lines.length&&line.includes('|')&&separator(lines[i+1])){
   const headers=cells(line);i+=2;const rows=[];
   while(i<lines.length&&lines[i].trim()&&lines[i].includes('|')){rows.push(cells(lines[i]));i++}
   out.push(`<div class="answer-table-wrap" role="region" aria-label="Response data" tabindex="0"><table><thead><tr>${headers.map(h=>`<th scope="col">${inline(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map((_,j)=>`<td>${inline(r[j]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);continue;
  }
  const heading=line.match(/^(#{1,4})\s+(.+)$/);
  if(heading){out.push(`<h${Math.min(heading[1].length+1,4)}>${inline(heading[2])}</h${Math.min(heading[1].length+1,4)}>`);i++;continue}
  const list=line.match(/^\s*(?:[-*]|\d+\.)\s+/);
  if(list){const ordered=/^\s*\d/.test(line),tag=ordered?'ol':'ul',items=[];while(i<lines.length&&/^\s*(?:[-*]|\d+\.)\s+/.test(lines[i])){items.push(`<li>${inline(lines[i++].replace(/^\s*(?:[-*]|\d+\.)\s+/,''))}</li>`)}out.push(`<${tag}>${items.join('')}</${tag}>`);continue}
  const paragraph=[line];i++;
  while(i<lines.length&&lines[i].trim()&&!/^(?:#{1,4}\s|\s*[-*]\s|\s*\d+\.\s)/.test(lines[i])&&!(i+1<lines.length&&separator(lines[i+1]))){paragraph.push(lines[i++])}
  out.push(`<p>${paragraph.map(inline).join('<br>')}</p>`);
 }
 return out.join('');
}
function newChat(){const store=conversationStore();if(activeConversation().messages.length){store.active=null;activeConversation()}saveConversations();state.view='chat';render();el('chat-query')?.querySelector('input')?.focus()}
function renderAnswer(message){const a=message.response;return `<article class="answer-card"><div class="answer-header">${icon('file')}Report analysis</div><div class="answer-text">${answerMarkdown(a.answer)}</div>${a.calculations?.length? `<details class="answer-workings"><summary>View calculations (${a.calculations.length})</summary>`+a.calculations.map(c=>`<div class="answer-calculation"><span class="small-label">Calculated · Deterministic arithmetic</span><code>${esc(c.formula)}\n${esc(c.inputs.join(', '))} → ${esc(c.result)} ${esc(c.unit)}</code></div>`).join('')+'</details>':''}${a.warnings?.length?`<details class="answer-caveats"><summary>Source notes (${a.warnings.length})</summary>${a.warnings.map(w=>`<div class="answer-warning">${esc(w)}</div>`).join('')}</details>`:''}<div class="answer-citations">${a.sources?.map(s=>cite(s)).join('')||''}</div><div class="answer-meta"><span>${esc(a.latency_ms)} ms</span><span>${a.sources?.length||0} source references</span><span>${a.composer==='llm'?'Evidence-constrained explanation':'Evidence-based response'}</span></div></article>`}
function chat(){const messages=activeConversation().messages;return `<div class="chat-workspace"><section class="chat-layout" aria-label="Report conversation"><header class="conversation-header"><div><h1>Query</h1><p>${esc(state.data.title)}</p></div><span>Source-grounded answers</span></header>${messages.length?'':`<div class="chat-intro"><div class="eyebrow">${icon('file')}${esc(state.data.title)}</div><h2 class="page-title">What would you like to explore?</h2><p>Ask about performance, explore the portfolio, or challenge a figure. Each answer comes with the evidence behind it.</p><div class="prompt-grid">${prompts.map(([label,q])=>`<button class="prompt-card" data-question="${esc(q)}"><span>${esc(label)}</span><strong>${esc(q)}</strong>${icon('arrow')}</button>`).join('')}</div></div>`}<div class="chat-messages" id="chat-messages" aria-live="polite">${messages.map(m=>`<div class="user-message">${esc(m.question)}</div>${m.response?renderAnswer(m):m.error?`<div class="chat-error">${esc(m.error)}</div>`:'<div class="answer-pending" role="status"><span class="pending-indicator" aria-hidden="true"></span>Preparing your answer…</div>'}`).join('')}</div><div class="chat-composer">${queryForm('chat-query','Ask a question about this report')}<p class="composer-note">${state.data.document.synthetic?'Synthetic fund data · ':''}Forecasts are projections · Source conflicts are disclosed</p></div></section>${chatHistory()}</div>`}
function quality(){const issues=state.data.issues.filter(x=>state.quality==='all'||(state.quality==='reviewed'?x.status==='reviewed':x.status==='open'&&x.severity===state.quality));return `${heading('Data Audit','Source observations and calculations, kept side by side')}<div class="quality-intro">${icon('shield')}<div><strong>No silent corrections</strong><p>The report’s original figures stay intact. Findings identify inconsistencies for review; they do not decide which source is correct.</p></div></div><div class="filter-bar" role="group" aria-label="Filter findings">${[['all',`All findings ${state.data.issues.length}`],['warning','Warnings'],['info','Notes'],['reviewed','Reviewed']].map(([k,l])=>`<button data-quality="${k}" class="${state.quality===k?'selected':''}" aria-pressed="${state.quality===k}">${l}</button>`).join('')}</div><div class="quality-list">${issues.map(i=>`<details class="quality-card"><summary><span class="severity-mark ${i.severity}">${icon(i.severity==='info'?'info':'warning')}</span><div><h2 class="quality-title">${esc(i.title)}</h2><p class="quality-description">${esc(i.description)}</p></div><span class="quality-status ${i.status==='reviewed'?'reviewed-label':''}">${i.status==='reviewed'?'Reviewed':i.severity==='info'?'Note':'Needs review'}</span>${icon('down')}</summary><div class="quality-detail">${i.details.reported!==undefined?`<div class="comparison"><div class="comparison-cell"><span>Source-reported</span><strong>${number(i.details.reported,2)}%</strong></div><div class="comparison-cell warning"><span>Calculated from NAV</span><strong>${number(i.details.computed,2)}%</strong></div></div>`:''}<div class="finding-details">${renderDetails(i.details)}</div><div class="quality-actions">${i.pages.map(p=>cite({page:p,section:'Source evidence'},`View page ${p}`)).join('')}<button class="button small review-button" data-review="${esc(i.id)}" data-status="${i.status==='reviewed'?'open':'reviewed'}">${icon(i.status==='reviewed'?'log':'check')}${i.status==='reviewed'?'Reopen finding':'Mark reviewed'}</button></div><div class="quality-rule">Rule: ${esc(i.rule)} · ${i.fact_ids.length} linked facts</div></div></details>`).join('')||'<div class="panel no-data"><h2>No findings in this view</h2><p>Choose another filter to inspect the report</p></div>'}</div>`}
function source(){const page=state.data.pages.find(x=>x.number===state.page)||state.data.pages[0];if(!page)return '<div class="no-data">No source pages available</div>';return `${heading('Vault','Inspect the original page alongside the extracted evidence')}<div class="source-layout"><nav class="source-pages" aria-label="Document pages">${state.data.pages.map(p=>`<button data-source-page="${p.number}" class="${p.number===state.page?'selected':''}" ${p.number===state.page?'aria-current="page"':''}><span class="page-number">${String(p.number).padStart(2,'0')}</span><span>${esc(p.section)}</span></button>`).join('')}</nav><div class="source-content"><div class="source-toolbar"><div class="source-controls"><button class="icon-button" data-page-step="-1" aria-label="Previous page" ${state.page<=1?'disabled':''}>${icon('left')}</button><label for="page-input" class="muted">Page</label><input type="number" id="page-input" min="1" max="${state.data.pages.length}" value="${state.page}" aria-label="Source page number"><span class="muted">of ${state.data.pages.length}</span><button class="icon-button" data-page-step="1" aria-label="Next page" ${state.page>=state.data.pages.length?'disabled':''}>${icon('right')}</button></div><div class="segmented" role="group" aria-label="Source view"><button data-source-mode="image" class="${state.sourceMode==='image'?'selected':''}">Original page</button><button data-source-mode="text" class="${state.sourceMode==='text'?'selected':''}">Extracted text</button></div><a class="button small" href="/documents/${state.id}/file" target="_blank" rel="noopener">Open PDF ${icon('external')}</a></div><div id="source-page-content">${state.sourceMode==='image'?`<div class="source-page"><img src="/documents/${state.id}/pages/${state.page}/image" alt="Original report, page ${state.page}: ${esc(page.section)}"></div>`:'<div class="source-text" id="source-raw-text">Loading page text…</div>'}</div><p class="source-caption">p. ${state.page} · ${esc(page.section)} · ${page.table_count} tables · ${esc(page.method)}</p><div class="source-facts"><h3>Extracted on this page</h3>${state.data.facts.filter(f=>f.source.page===state.page).map(f=>`<div class="fact-row"><span>${esc(f.category||shortMetric(f.metric))} · ${esc(f.period)} <span class="muted">${f.classification==='forecast'?'· Forecast':''}</span></span><strong>${number(f.value,f.unit==='percent'?1:2)} ${esc(f.unit)}</strong></div>`).join('')||'<p class="secondary">Narrative or visual evidence · No structured facts identified</p>'}</div></div></div>`}
function extraction(){const d=state.data.document,e=state.data.extraction;return `${heading('Trace','A transparent path from the original PDF to usable evidence')}<div class="log-stats"><div class="log-stat"><strong>${d.page_count}</strong><span>Pages processed</span></div><div class="log-stat"><strong>${d.fact_count}</strong><span>Structured facts</span></div><div class="log-stat"><strong>${d.table_count}</strong><span>Tables extracted</span></div></div><div class="extraction-notice">${icon('info')} ${esc(e.retrieval_description)} ${esc(e.ocr_description)}</div><section class="panel"><div class="panel-header"><h2 class="panel-title">Processing pipeline</h2><span class="panel-subtitle">Version ${esc(d.pipeline_version)}</span></div><div class="pipeline">${e.stages.map(s=>`<div class="pipeline-step"><span class="step-check">${icon('check')}</span><div class="step-content"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p></div><span class="pipeline-meta">${number(s.duration_ms,0)} ms</span></div>`).join('')}</div></section><section class="panel log-panel"><div class="panel-header"><h2 class="panel-title">Page inventory</h2><span class="panel-subtitle">Original text preserved</span></div><div class="table-wrap page-inventory"><table><thead><tr><th>Page</th><th>Section</th><th>Characters</th><th>Tables</th><th>Method</th><th>Review</th></tr></thead><tbody>${state.data.pages.map(p=>`<tr><td>${pageButton(p.number)}</td><td>${esc(p.section)}</td><td class="mono">${number(p.char_count,0)}</td><td class="mono">${p.table_count}</td><td>${esc(p.method)}</td><td>${p.warnings.length?`<span class="row-warning" title="${esc(p.warnings.join('; '))}">Review</span>`:'Extracted'}</td></tr>`).join('')}</tbody></table></div></section><section class="panel log-panel"><div class="pipeline"><h3>Document fingerprint</h3><p class="secondary" style="font-size:12px;margin-top:8px">SHA-256 identifies identical uploads. Raw page text, table cells, and coordinates are retained for reprocessing.</p><p class="mono" style="font-size:11px;overflow-wrap:anywhere;margin-top:12px">${esc(d.checksum)}</p></div></section>`}
const architectureSteps=[
 ['Upload & register','PDF · SHA-256 fingerprint','The upload endpoint checks file format, size and page count. A SHA-256 fingerprint identifies duplicate uploads. The original PDF is preserved on disk.','app/main.py · app/pipeline.py'],
 ['Extract pages','pdfplumber · optional OCR','Extract native text, tables, cell coordinates and chart geometry. Low-text pages use Tesseract when available; otherwise extraction limitations are flagged.','app/extraction.py'],
 ['Normalize facts','Values · periods · provenance','Convert financial table cells into typed facts. Keep the raw token, source units, period, page and table coordinates alongside each observation.','app/extraction.py'],
 ['Check consistency','Findings, not corrections','Check NAV/return reconciliation, repeated quarterly versions and extraction quality. Conflicts become findings; original values stay intact.','app/validation.py'],
 ['Store & index evidence','Database + original files','Create overlapping, page-aware narrative chunks. Commit facts, chunks, findings and completed document state together through SQLAlchemy. PostgreSQL or SQLite stores records; PDFs and extraction JSON remain on disk. Embeddings are not generated by this ingestion pipeline.','app/pipeline.py · app/db.py'],
 ['Analyse the question','Structured or narrative route','The current router uses patterns and available report periods. Numeric lookups, comparisons and calculations use structured facts. Narrative questions use passage retrieval. This routing step does not call an LLM.','app/answering.py'],
 ['Look up & calculate','Structured facts · Decimal arithmetic','Select the requested financial observations and calculate supported differences, growth or compounding deterministically. This route bypasses BM25, vector search and LLM composition.','app/answering.py · app/calculations.py'],
 ['Retrieve keywords','BM25 · page-aware passages','Rank narrative chunks by keyword relevance, with section names weighted in the index. Certain intents prefer relevant narrative sections. Retrieval stays scoped to the selected document.','app/retrieval.py · app/answering.py'],
 ['Retrieve by meaning','Optional embeddings · pgvector','When embeddings are enabled, the first semantic query lazily generates missing chunk vectors. Local BGE-small or OpenAI creates embeddings; pgvector stores and searches them in PostgreSQL using cosine distance and an HNSW index. SQLite uses JSON vectors and in-memory cosine ranking instead. Semantic and keyword passages are combined, deduplicated and bounded.','app/vector.py · app/provider.py'],
 ['Compose & check','Optional Claude or OpenAI','When enabled, the configured model receives bounded retrieved passages. Its returned citation pages must belong to that evidence, and new numeric tokens are rejected. If composition fails or is disabled, the app shows extracted source passages. No LLM is needed for structured answers.','app/provider.py · app/answering.py'],
 ['Return a cited answer','Sources · caveats · audit trail','Attach source pages, fact IDs, calculation details and related data-quality warnings. Save query metadata and calculations in the database. The UI renders the answer and keeps conversation history in this browser.','app/answering.py · app/main.py · ui/app.js']
];
