function architectureDiagram(){
 const path=architecturePath(),a=architectureState;
 const links=architectureEdges.map(([from,to,d,route],i)=>{const chosen=route==='all'||route===a.route;return `<g class="architecture-edge ${chosen?'':'inactive'}" data-edge-route="${route}" aria-hidden="true"><path class="architecture-wire" d="${d}"/><path id="architecture-edge-${i}" class="architecture-signal" pathLength="1" d="${d}" style="--draw-delay:${Math.min(i*.13,.9)}s"/><circle class="architecture-packet" r="3"><animateMotion dur="${2.6+i%3*.3}s" begin="${1.2+i*.14}s" repeatCount="indefinite"><mpath href="#architecture-edge-${i}"/></animateMotion></circle></g>`}).join('');
 const nodes=architecturePositions.map(([x,y,w,h],i)=>{const [title,subtitle]=architectureLabels[i];return `<g class="architecture-map-node ${path.includes(i)?'':'inactive'} ${a.step===i?'active':''}" role="button" tabindex="0" aria-label="${esc(architectureSteps[i][0])}" data-architecture-step="${i}" transform="translate(${x} ${y})" style="--node-delay:${i===4?0:i*.12}s"><rect class="architecture-map-card" width="${w}" height="${h}" rx="10"/><text class="architecture-map-index" x="16" y="22">${String(i+1).padStart(2,'0')}${i===4?' · SHARED STORAGE':''}</text><text class="architecture-map-title" x="16" y="45">${esc(title)}</text><text class="architecture-map-subtitle" x="16" y="65">${esc(subtitle)}</text>${i===4?'<text class="architecture-map-subtitle" x="16" y="88">PostgreSQL / SQLite + files</text>':''}</g>`}).join('');
 return `<div class="architecture-map-scroll" tabindex="0" role="region" aria-label="Interactive product architecture"><svg id="architecture-map" class="architecture-map" viewBox="0 0 1208 678" role="group" aria-label="Report ingestion and branched question-answering workflow"><defs><pattern id="architecture-grid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="var(--line)"/></pattern></defs><rect width="1208" height="678" fill="url(#architecture-grid)"/><text class="architecture-map-lane" x="24" y="30">Document ingestion</text><text class="architecture-map-lane" x="316" y="270">Knowledge base</text><text class="architecture-map-lane" x="602" y="30">Question & retrieval</text><text class="architecture-map-lane" x="924" y="30">Answer generation</text>${links}${nodes}<text class="architecture-map-caption" x="24" y="616">Every observation retains its original page and source units.</text><text class="architecture-map-caption" x="24" y="640">Optional services illustrate available paths, not live provider activity.</text></svg></div>`;
}
function architecture(){const a=architectureState;return `${heading('Engine','From source document to a cited answer',false)}<div class="architecture-controls"><div class="segmented" role="group" aria-label="Illustrated answer path"><button data-architecture-route="narrative" class="${a.route==='narrative'?'selected':''}" aria-pressed="${a.route==='narrative'}">Narrative question</button><button data-architecture-route="structured" class="${a.route==='structured'?'selected':''}" aria-pressed="${a.route==='structured'}">Numeric question</button></div><div><button class="button small" id="architecture-play">${a.playing?'Pause':'Play'}</button> <button class="button small" id="architecture-replay">Replay</button></div></div><section class="architecture-map-panel panel">${architectureDiagram()}<div class="architecture-map-legend"><span><i></i>Selected workflow</span><span><i class="dim"></i>Alternative path</span><span>Moving markers illustrate data flow · No API calls</span></div></section><p class="architecture-footnote">The diagram draws itself into view and animates the selected route. Semantic embeddings are created lazily on the first semantic query; numeric questions bypass retrieval and model composition. Reduced-motion preferences show a static diagram.</p>`}
function paintArchitecture(){
 const a=architectureState,path=architecturePath(),step=architectureSteps[a.step];
 el('main').querySelectorAll('.architecture-map-node').forEach(n=>{const i=Number(n.dataset.architectureStep);n.classList.toggle('active',i===a.step);n.classList.toggle('visited',path.includes(i)&&path.indexOf(i)<path.indexOf(a.step));if(i===a.step)n.setAttribute('aria-current','step');else n.removeAttribute('aria-current')});

 const button=el('architecture-play');if(button)button.textContent=a.playing?'Pause':'Play';
 const svg=el('architecture-map');if(svg){svg.classList.toggle('paused',!a.playing);if(a.playing)svg.unpauseAnimations();else svg.pauseAnimations()}
}
function startArchitecture(){
 clearTimeout(architectureState.timer);
 if(state.view!=='architecture')return;
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)architectureState.playing=false;
 paintArchitecture();if(!architectureState.playing)return;
 architectureState.timer=setTimeout(()=>{if(state.view!=='architecture')return;const path=architecturePath(),next=path.indexOf(architectureState.step)+1;if(next>=path.length)architectureState.playing=false;else architectureState.step=path[next];startArchitecture()},2400);
}
function render(){clearTimeout(architectureState.timer);const footer=document.querySelector('.main-footer span');if(footer&&state.data)footer.textContent=state.data.document.synthetic?'Synthetic fund data · For demonstration only':'Private report · Source values preserved';nav();if(!state.data)return;el('main').classList.remove('overview-enter');el('main').classList.toggle('chat-page',state.view==='chat');el('main').innerHTML=({overview,chat,source,quality,extraction,architecture,connect}[state.view]||overview)();bind();animateOverview();startArchitecture();if(state.view==='source'&&state.sourceMode==='text')loadPageText();if(state.view==='source')el('main').querySelector('.source-pages .selected')?.scrollIntoView({block:'nearest',inline:'nearest'})}
function bind(){
 el('save-llm')?.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget),provider=data.get('provider'),apiKey=String(data.get('apiKey')||'').trim(),pass=String(data.get('passphrase')||''),feedback=el('connect-feedback');if(pass!==data.get('confirmPassphrase')){feedback.textContent='Passphrases do not match.';return}if(apiKey.length<20||apiKey.length>300){feedback.textContent='Check the key and try again.';return}const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{const sealed=await sealCredentials(provider,apiKey,pass);localStorage.setItem(LLM_STORAGE,JSON.stringify(sealed));state.llm={provider,apiKey};state.connectEdit=false;render();toast('Provider key encrypted and unlocked for this session.')}catch(err){feedback.textContent=err.name==='QuotaExceededError'?'Browser storage is full; the encrypted key was not saved.':err.message}finally{button.disabled=false}});
 el('unlock-llm')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{state.llm=await openCredentials(JSON.parse(localStorage.getItem(LLM_STORAGE)||'null'),new FormData(e.currentTarget).get('passphrase'));state.connectEdit=false;render();toast('Provider key unlocked for this session.')}catch{el('connect-feedback').textContent='Could not unlock. Check the passphrase.'}finally{button.disabled=false}});
 el('lock-llm')?.addEventListener('click',()=>{state.llm=null;render()});
 el('remove-llm')?.addEventListener('click',()=>{state.llm=null;localStorage.removeItem(LLM_STORAGE);state.connectEdit=true;render();toast('Encrypted provider key removed from this browser.')});
 el('change-llm')?.addEventListener('click',()=>{state.connectEdit=true;render()});el('replace-llm')?.addEventListener('click',()=>{state.connectEdit=true;render()});

 el('main').querySelectorAll('[data-architecture-step]').forEach(b=>{const select=()=>{architectureState.step=Number(b.dataset.architectureStep);architectureState.playing=false;startArchitecture()};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});
 el('main').querySelectorAll('[data-architecture-route]').forEach(b=>b.onclick=()=>{architectureState.route=b.dataset.architectureRoute;architectureState.step=0;architectureState.playing=true;render()});
 el('architecture-play')?.addEventListener('click',()=>{architectureState.playing=!architectureState.playing;if(architectureState.step===10)architectureState.step=0;startArchitecture()});
 el('architecture-replay')?.addEventListener('click',()=>{architectureState.step=0;architectureState.playing=true;render()});
 el('new-chat')?.addEventListener('click',newChat);
 el('main').querySelectorAll('[data-conversation]').forEach(b=>b.addEventListener('click',()=>openConversation(b.dataset.conversation)));
 el('main').querySelectorAll('[data-upload]').forEach(b=>b.addEventListener('click',openUpload));
 el('main').querySelectorAll('[data-export]').forEach(b=>b.addEventListener('click',exportFindings));
 el('main').querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{state.range=b.dataset.range;render()}));
 el('main').querySelectorAll('[data-quality]').forEach(b=>b.addEventListener('click',()=>{state.quality=b.dataset.quality;render()}));
 el('main').querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.question)));
 el('main').querySelectorAll('.query-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const q=new FormData(f).get('question')?.trim();if(q)ask(q)}));
 el('main').querySelectorAll('[data-evidence]').forEach(b=>{b.addEventListener('click',()=>openEvidence(Number(b.dataset.evidence)));if(b.tagName.toLowerCase()==='rect')b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openEvidence(Number(b.dataset.evidence))}})});
 el('main').querySelectorAll('[data-chart-year]').forEach(b=>{const show=()=>{const t=el('chart-tooltip');if(t){t.innerHTML=`${esc(b.dataset.chartYear)} · ${b.dataset.chartForecast==='true'?'Forecast':'Historical'}<strong>${number(b.dataset.chartNav,1)}</strong>p. ${esc(b.dataset.chartPage)} · Click to inspect`;t.hidden=false}};b.addEventListener('mouseenter',show);b.addEventListener('focus',show);b.addEventListener('mouseleave',()=>{if(el('chart-tooltip'))el('chart-tooltip').hidden=true});b.addEventListener('blur',()=>{if(el('chart-tooltip'))el('chart-tooltip').hidden=true})});
 el('main').querySelectorAll('[data-source-page]').forEach(b=>b.addEventListener('click',()=>{state.page=Number(b.dataset.sourcePage);render()}));
 el('main').querySelectorAll('[data-page-step]').forEach(b=>b.addEventListener('click',()=>{state.page=Math.max(1,Math.min(state.data.pages.length,state.page+Number(b.dataset.pageStep)));render()}));
 el('main').querySelectorAll('[data-source-mode]').forEach(b=>b.addEventListener('click',()=>{state.sourceMode=b.dataset.sourceMode;render()}));
 el('page-input')?.addEventListener('change',e=>{state.page=Math.max(1,Math.min(state.data.pages.length,Number(e.target.value)||1));render()});
 el('main').querySelectorAll('[data-review]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await api(`/documents/${state.id}/validation/${encodeURIComponent(b.dataset.review)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:b.dataset.status})});const i=state.data.issues.find(i=>i.id===b.dataset.review);i.status=b.dataset.status;render();toast(i.status==='reviewed'?'Finding marked reviewed. Source data is unchanged.':'Finding reopened')}catch(e){toast(e.message);b.disabled=false}}));
}
async function ask(question){
 if(state.asking)return toast('An answer is already being prepared');if(!state.id||!state.data)return;
 const documentId=state.id,thread=activeConversation(),message={question},started=performance.now();
 state.asking=true;thread.messages.push(message);if(thread.messages.length===1)thread.title=question.slice(0,80);thread.updated=Date.now();saveConversations();
 state.view='chat';if(location.hash!=='#chat')history.pushState(null,'','#chat');render();
 el('chat-messages')?.lastElementChild?.scrollIntoView({block:'nearest',behavior:'smooth'});
 // One request only. A short presentation delay keeps instant local answers readable.
 try{const [response]=await Promise.all([api('/chat/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:documentId,question,...(state.llm?{provider:state.llm.provider,api_key:state.llm.apiKey}:{})})}),new Promise(resolve=>setTimeout(resolve,1000))]);message.response=response}
 catch(e){message.error=e.message}
 finally{state.asking=false;thread.updated=Date.now();saveConversations();if(state.id===documentId&&state.view==='chat'){const isCurrent=activeConversation().id===thread.id;render();if(isCurrent){el('chat-messages')?.lastElementChild?.scrollIntoView({block:'nearest',behavior:'smooth'});el('chat-query')?.querySelector('input')?.focus({preventScroll:true})}}}
}

let previousFocus;
function closeEvidence(){el('evidence-drawer').hidden=true;el('drawer-backdrop').hidden=true;document.body.style.overflow='';previousFocus?.focus?.()}
async function openEvidence(page){if(!Number.isInteger(page)||page<1||page>state.data.pages.length)return;previousFocus=document.activeElement;const drawer=el('evidence-drawer');el('drawer-backdrop').hidden=false;drawer.hidden=false;drawer.dataset.page=String(page);drawer.innerHTML=`<div class="drawer-heading"><h2>Source evidence</h2><button class="icon-button" id="close-evidence" aria-label="Close source evidence">${icon('close')}</button></div><div class="source-controls">${icon('file')}Page ${page} of ${state.data.document.page_count}</div><div class="source-page"><img src="/documents/${state.id}/pages/${page}/image" alt="Original source page ${page}"></div><div id="drawer-details" class="drawer-section">Loading extraction details…</div>`;document.body.style.overflow='hidden';el('close-evidence').onclick=closeEvidence;el('close-evidence').focus();const docId=state.id;try{const p=await api(`/documents/${docId}/pages/${page}`);if(drawer.hidden||state.id!==docId||drawer.dataset.page!==String(page))return;el('drawer-details').innerHTML=`<strong>${esc(p.section)}</strong><div class="source-facts">${state.data.facts.filter(f=>f.source.page===page).slice(0,24).map(f=>`<div class="fact-row"><span>${esc(f.category||shortMetric(f.metric))} · ${esc(f.period)}</span><strong>${number(f.value,f.unit==='percent'?1:2)} ${esc(f.unit)}</strong></div>`).join('')}</div><details style="margin-top:20px"><summary>Raw extracted text</summary><div class="raw-text">${esc(p.text)}</div></details><p class="provenance-label">${esc(p.method)} · Original page preserved · Page numbering follows PDF order</p><a class="button small" style="margin-top:16px" href="/documents/${docId}/file#page=${page}" target="_blank" rel="noopener">Open original PDF ${icon('external')}</a>`}catch(e){if(el('drawer-details'))el('drawer-details').textContent=e.message}}
async function loadPageText(){const doc=state.id,page=state.page;try{const p=await api(`/documents/${doc}/pages/${page}`);if(doc===state.id&&page===state.page&&el('source-raw-text'))el('source-raw-text').textContent=p.text||'No text extracted on this page'}catch(e){if(el('source-raw-text'))el('source-raw-text').textContent=e.message}}
function exportFindings(){const d=state.data;const rows=(items,forecast=false)=>items.map(r=>`<tr><td>${esc(r.year)}</td><td>${number(r.nav,2)}</td><td>${number(r.fund_return)}%</td><td>${forecast?number(r.aum,0):number(r.benchmark_return)+'%'}</td><td>p. ${r.page}</td></tr>`).join('');const content=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(d.title)} · Findings</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f2;color:#223027;font:15px/1.65 system-ui,sans-serif}main{max-width:1040px;margin:32px auto;background:white;padding:48px;border:1px solid #dce4dc;border-radius:12px}h1{font:40px/1.2 Georgia,serif;margin:8px 0 16px}h2{font-size:21px;margin:32px 0 12px}h3{font-size:16px;margin:0 0 8px}p{margin:8px 0;color:#536459}.meta{font-size:12px;color:#536459}.stats{display:flex;gap:32px;border-block:1px solid #dce4dc;padding:20px 0;margin:24px 0}.stats b{display:block;font-size:26px;color:#226644}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px;text-align:right;border-bottom:1px solid #e2e8e1}th:first-child,td:first-child{text-align:left}th{color:#536459;font-weight:500}.issue{padding:20px 0;border-bottom:1px solid #e2e8e1}.tag{font-size:11px;color:#805e22}.note{padding:16px;background:#f2f5f0;border-left:3px solid #226644}.toolbar{display:flex;gap:12px;justify-content:flex-end}button{padding:10px 16px;background:#223027;color:#fff;border:0;border-radius:6px;cursor:pointer}footer{margin-top:36px;border-top:1px solid #dce4dc;padding-top:16px;font-size:11px;color:#536459}@media(max-width:640px){main{padding:24px;margin:12px}h1{font-size:30px}.stats{gap:16px;flex-wrap:wrap}.table{overflow:auto}}@media print{@page{margin:16mm}body{background:white}main{margin:0;padding:0;border:0;max-width:none}.toolbar{display:none}.issue,tr{break-inside:avoid}h2{break-after:avoid}thead{display:table-header-group}}</style></head><body><main><div class="toolbar"><button onclick="window.print()">Print / Save PDF</button><button id="download">Download HTML</button></div><p class="meta">Financial document intelligence · Findings report</p><h1>${esc(d.title)}</h1><p>${esc(d.document.filename)}</p><p class="meta">Prepared ${esc(new Date().toLocaleDateString('en-GB'))} · Source values preserved · Page numbers follow PDF order</p><div class="stats"><div><b>${d.document.page_count}</b>Pages</div><div><b>${d.facts.length}</b>Source observations</div><div><b>${d.issues.filter(i=>i.severity!=='info').length}</b>Warnings</div><div><b>${d.issues.filter(i=>i.severity==='info').length}</b>Notes</div></div><p class="note">${d.document.synthetic?'All fund figures are fictional demonstration data. ':''}Reported values, forecasts, and derived calculations are kept separate. Findings identify discrepancies; they do not silently correct the source.</p><h2>Historical annual performance</h2><div class="table"><table><thead><tr><th>Year</th><th>NAV units</th><th>Fund return</th><th>Benchmark</th><th>Source</th></tr></thead><tbody>${rows(d.annual)}</tbody></table></div><h2>Forecast outlook</h2><p class="meta">Scenario projections, not historical outcomes · Currency glyph remains unresolved where noted in the source</p><div class="table"><table><thead><tr><th>Year</th><th>NAV units</th><th>Expected return</th><th>AUM (crore)</th><th>Source</th></tr></thead><tbody>${rows(d.forecast,true)}</tbody></table></div><h2>Data-quality findings</h2>${d.issues.map(i=>`<section class="issue"><div class="tag">${esc(i.severity==='info'?'Informational note':'Needs review')} · ${esc(i.status)}</div><h3>${esc(i.title)}</h3><p>${esc(i.description)}</p><p class="meta">Evidence: ${i.pages.map(p=>'p. '+p).join(', ')}${i.details.formula?' · Formula: '+esc(i.details.formula):''}</p></section>`).join('')}<h2>Portfolio distributions</h2>${d.allocations.map(g=>`<h3>${esc(g.name)} · p. ${g.page}</h3><p>${g.rows.map(r=>esc(r.category)+': '+number(r.value,1)+'%').join(' · ')}</p>`).join('')}<footer>Document fingerprint: ${esc(d.document.checksum)}<br>Extracted observations remain traceable to the original report. Review unresolved findings before using any figure.</footer></main><script>document.getElementById('download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['<!doctype html>'+document.documentElement.outerHTML],{type:'text/html;charset=utf-8'}));a.download='fund-findings.html';a.click()};<\/script></body></html>`;let dialog=document.getElementById('findings-preview');if(!dialog){dialog=document.createElement('dialog');dialog.id='findings-preview';dialog.style.cssText='width:96vw;max-width:1200px;height:94vh;padding:0;border:1px solid #dce4dc;border-radius:12px;background:#f4f6f2';dialog.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 20px;background:#fff;color:#223027;font:14px system-ui"><strong>Findings report</strong><button aria-label="Close findings report" style="padding:8px 14px;border:1px solid #dce4dc;border-radius:6px;background:white;color:#223027;cursor:pointer">Close</button></div><iframe title="Printable findings report" style="display:block;width:100%;height:calc(100% - 58px);border:0"></iframe>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close()}dialog.querySelector('iframe').srcdoc=content;dialog.showModal();}
function openUpload(){el('upload-feedback').textContent='';el('upload-dialog').showModal()}
function documentMenu(){const d=state.documents.find(d=>d.id===state.id);el('active-filename').textContent=d?.filename||'No report selected';el('sidebar-doc-meta').textContent=d?`${d.page_count} pages · ${d.status==='completed'?'Evidence ready':d.status}`:'Upload a PDF to get started';el('document-list').innerHTML=state.documents.map(d=>`<button data-doc-id="${esc(d.id)}">${esc(d.filename)} · ${d.page_count} pp.</button>`).join('')+`<button id="add-from-menu" ${hostedVercel?'hidden':''}>+ Add a report</button>`;el('document-list').querySelectorAll('[data-doc-id]').forEach(b=>b.onclick=()=>{el('document-list').hidden=true;selectDocument(b.dataset.docId)});el('add-from-menu').onclick=()=>{el('document-list').hidden=true;openUpload()}}
async function selectDocument(id){clearTimeout(state.poll);state.id=id;state.data=null;state.page=1;try{localStorage.setItem('fund-document',id)}catch{}documentMenu();await loadDocument(id)}
async function loadDocument(id){try{const d=await api(`/documents/${id}`);if(state.id!==id)return;if(d.status==='completed'){const overviewData=await api(`/documents/${id}/overview`);if(state.id!==id)return;state.data=overviewData;if(overviewData.document.service_notice)toast(overviewData.document.service_notice);const i=state.documents.findIndex(x=>x.id===id);if(i>=0)state.documents[i]=d;documentMenu();render()}else if(d.status==='failed'){el('main').innerHTML=`${heading('Extraction needs attention','The source file is preserved for investigation')}<div class="panel no-data"><h2>We couldn’t finish this report</h2><p>${esc(d.error||'An extraction error occurred')}</p><button class="button primary" id="retry-ingestion">Retry extraction</button> <button class="button" data-upload>Add another PDF</button></div>`;bind();el('retry-ingestion').onclick=async()=>{try{await api(`/documents/${id}/retry`,{method:'POST'});loadDocument(id)}catch(e){toast(e.message)}}}else{nav();el('main').innerHTML=`<div class="loading-state"><div class="loading-line"></div><h1>Turning the report into evidence</h1><p>${esc(d.stage)}</p><div class="progress-track"><div style="width:${d.progress}%"></div></div><div class="loading-progress">${d.progress}% · ${esc(d.filename)}</div></div>`;state.poll=setTimeout(()=>loadDocument(id),1200)}}catch(e){el('main').innerHTML=`<div class="no-data"><h2>Couldn’t open the workspace</h2><p>${esc(e.message)}</p><button class="button" id="reload-app">Try again</button></div>`;el('reload-app').onclick=init}}
async function upload(e){e.preventDefault();const file=el('file-input').files[0];if(!file)return;if(file.size>25*1024*1024){el('upload-feedback').textContent='Please choose a PDF smaller than 25 MB';return}const b=el('upload-submit');b.disabled=true;b.textContent='Uploading…';el('upload-feedback').textContent='';try{const data=new FormData();data.append('file',file);const d=await api('/documents/upload',{method:'POST',body:data});el('upload-dialog').close();state.documents=await api('/documents');await selectDocument(d.id);toast(d.duplicate?'This document is already in your workspace':'Report uploaded. Extraction is underway.')}catch(e){el('upload-feedback').textContent=e.message}finally{b.disabled=false;b.textContent='Extract report'}}
async function init(){nav();try{state.documents=await api('/documents');let previous;try{previous=localStorage.getItem('fund-document')}catch{}const d=state.documents.find(d=>d.id===previous)||state.documents[0];if(d)await selectDocument(d.id);else{documentMenu();el('main').innerHTML=`${heading('Your report, with the evidence','Upload a fund report to start your research',false)}<div class="panel no-data">${icon('file')}<h2 style="margin-top:16px">Start with the source</h2><p>Extract tables, inspect inconsistencies, and ask evidence-backed questions</p><button class="button primary" data-upload ${hostedVercel?'hidden':''}>${icon('upload')}Upload a PDF</button></div>`;bind()}}catch(e){el('main').innerHTML=`<div class="no-data"><h2>The application is unavailable</h2><p>${esc(e.message)}</p><button class="button" onclick="location.reload()">Retry</button></div>`}}
el('document-icon').innerHTML=icon('file');el('document-chevron').innerHTML=icon('down');el('privacy-icon').innerHTML=icon('lock');el('upload-icon').innerHTML=icon('upload');el('mobile-menu').innerHTML=icon('menu');el('close-upload').innerHTML=icon('close');el('light-theme').innerHTML=icon('sun')+'Light';el('dark-theme').innerHTML=icon('moon')+'Dark';theme(document.documentElement.dataset.theme);el('light-theme').onclick=()=>theme('light');el('dark-theme').onclick=()=>theme('dark');el('mobile-menu').onclick=()=>el('sidebar').classList.toggle('open');el('close-upload').onclick=()=>el('upload-dialog').close();el('document-menu').onclick=()=>el('document-list').hidden=!el('document-list').hidden;el('drawer-backdrop').onclick=closeEvidence;el('upload-form').onsubmit=upload;el('file-input').onchange=()=>el('upload-filename').textContent=el('file-input').files[0]?.name||'';
const dz=el('dropzone');['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('dragover')}));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('dragover')}));dz.addEventListener('drop',e=>{if(e.dataTransfer.files.length){const dt=new DataTransfer();dt.items.add(e.dataTransfer.files[0]);el('file-input').files=dt.files;el('file-input').dispatchEvent(new Event('change'))}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);state.view=views.some(x=>x[0]===v)?v:'overview';el('sidebar').classList.remove('open');render();window.scrollTo({top:0})});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!el('evidence-drawer').hidden)closeEvidence();el('sidebar').classList.remove('open');el('document-list').hidden=true}if(e.key==='Tab'&&!el('evidence-drawer').hidden){const focusable=[...el('evidence-drawer').querySelectorAll('button,a,summary')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus()}}});document.addEventListener('click',e=>{if(!e.target.closest('.sidebar-document'))el('document-list').hidden=true});
state.view=views.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview';init();
